"""Record tested dependency versions with the Windows-only dependency marked."""

import subprocess
import sys
from pathlib import Path


def main():
    lines = subprocess.check_output(
        [sys.executable, "-m", "pip", "freeze", "--exclude-editable"], text=True
    ).splitlines()
    lines = [
        line + '; sys_platform == "win32"' if line.startswith("pywin32==") else line
        for line in lines
        if not line.startswith(("-e ", "self-hosted-web-tools"))
    ]
    root = Path(__file__).resolve().parents[1]
    (root / "requirements.lock").write_text(
        "# Generated by scripts/lock_dependencies.py; includes development tools.\n"
        + "\n".join(lines)
        + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
